package com.example.estatex.common;

import java.util.List;
import org.flywaydb.core.Flyway;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.flyway.autoconfigure.FlywayMigrationStrategy;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;

/**
 * Transitional Flyway setup. The legacy schema (~40 tables) is still generated by Hibernate's
 * {@code ddl-auto=update}, so on a fresh database those tables don't exist until the JPA
 * EntityManagerFactory has started. Spring Boot normally runs Flyway <em>before</em> JPA, which
 * would make any migration that touches a Hibernate-managed table fail on a fresh database.
 *
 * <p>So the startup-time migration is a no-op, and migrations are applied instead by a
 * {@link CommandLineRunner} at the highest precedence: after Hibernate has created/updated every
 * table, and before any seeder or backfill runner. Migrations therefore only hold what Hibernate
 * can't do well: versioned data fixes, enum check-constraint repairs, indexes and constraints.
 *
 * <p>Moving to full Flyway ownership ({@code ddl-auto=validate}) requires a V1 baseline taken
 * from the production Postgres schema, tracked in docs/estatex-integration-plan.md.
 */
@Configuration
class FlywayAfterHibernateConfig {

    @Bean
    FlywayMigrationStrategy deferFlywayUntilAfterHibernate() {
        return flyway -> { };
    }

    @Bean
    @Order(Ordered.HIGHEST_PRECEDENCE)
    CommandLineRunner flywayMigrateAfterHibernate(Flyway flyway) {
        return args -> {
            List<String> problems = MigrationGuard.classpathProblems();
            if (!problems.isEmpty()) {
                throw new IllegalStateException("Refusing to run database migrations:\n  - "
                        + String.join("\n  - ", problems)
                        + "\nRemove the file (run ./mvnw clean if it was already deleted from src), or mark a deliberate"
                        + " destructive statement with '-- reviewed-destructive: <reason>' on the line above.");
            }
            flyway.migrate();
        };
    }
}
